    case 'pantavion-kernel-governor':
      return upsertProviderHealth({
        adapterKey: adapter.adapterKey,
        status: 'healthy',
        successRate: 0.998,
        latencyMs: 18,
        incidents: 0,
        notes: ['Primary governed kernel adapter.'],
      });

